KEY_MISSING"; exit 1; fi && echo "key_loaded chars=${#TYPESAFE_API_KEY}" && umask 077 && code=$(curl -sS -o /tmp/jev-op-identity-response.json -w "%{http_code}" --max-time 120 -H "Authorization: *** ${TYPESAFE_API_KEY}" -H "Content-Type: application/json" --data-binary @/tmp/jev-op-identity-request.json https://api.typesafe.ai/v1/systemone) && echo "http=$code" && python3 -c 'import json; d=json.load(open("/tmp/jev-op-identity-response.json")); print("model", d.get("model")); print("usage", d.get("usage"));
ans=d.get("answers") or {}
print("n_answers", len(ans))
for k,v in ans.items():
    probs=v.get("probabilities") or {}
    rh=probs.get("removed_hand_rolled_bridge")
    print(f"{k}\tchoice={v.get(\"choice\")}\tconf={v.get(\"confidence\")}\tremoved={rh}")'","description":"Classify op-identity references with JEV"}

